package com.rohit.inventory.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="inventory_transactions") public class InventoryTransaction extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="warehouse_id",nullable=false) private Warehouse warehouse; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="zone_id",nullable=false) private WarehouseZone zone; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="product_id",nullable=false) private Product product; @Enumerated(EnumType.STRING) @Column(name="transaction_type",nullable=false) private InventoryTransactionType transactionType; @Column(name="quantity_delta",nullable=false) private BigDecimal quantityDelta; @Column(name="previous_on_hand_quantity",nullable=false) private BigDecimal previousOnHandQuantity; @Column(name="resulting_on_hand_quantity",nullable=false) private BigDecimal resultingOnHandQuantity; @Column(name="previous_reserved_quantity",nullable=false) private BigDecimal previousReservedQuantity; @Column(name="resulting_reserved_quantity",nullable=false) private BigDecimal resultingReservedQuantity; @Column(name="reference_type") private String referenceType; @Column(name="reference_id") private UUID referenceId; private String reason; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="performed_by") private User performedBy; @Column(name="occurred_at",nullable=false) private Instant occurredAt=Instant.now(); public void setWarehouse(Warehouse v){warehouse=v;} public void setZone(WarehouseZone v){zone=v;} public void setProduct(Product v){product=v;} public void setTransactionType(InventoryTransactionType v){transactionType=v;} public void setQuantityDelta(BigDecimal v){quantityDelta=v;} public void setPreviousOnHandQuantity(BigDecimal v){previousOnHandQuantity=v;} public void setResultingOnHandQuantity(BigDecimal v){resultingOnHandQuantity=v;} public void setPreviousReservedQuantity(BigDecimal v){previousReservedQuantity=v;} public void setResultingReservedQuantity(BigDecimal v){resultingReservedQuantity=v;} public void setReferenceType(String v){referenceType=v;} public void setReferenceId(UUID v){referenceId=v;} public void setReason(String v){reason=v;} public void setPerformedBy(User v){performedBy=v;} public Warehouse getWarehouse(){return warehouse;} public WarehouseZone getZone(){return zone;} public Product getProduct(){return product;} public InventoryTransactionType getTransactionType(){return transactionType;} public BigDecimal getQuantityDelta(){return quantityDelta;} public BigDecimal getPreviousOnHandQuantity(){return previousOnHandQuantity;} public BigDecimal getResultingOnHandQuantity(){return resultingOnHandQuantity;} public BigDecimal getPreviousReservedQuantity(){return previousReservedQuantity;} public BigDecimal getResultingReservedQuantity(){return resultingReservedQuantity;} public String getReason(){return reason;} public Instant getOccurredAt(){return occurredAt;} }
